#include <Arduino.h>
#include <esp_heap_caps.h>
#include "lottie_demo.h"

/* Generated by tools/lottie_to_c.py. NUL terminated, which lv_lottie requires. */
extern "C" {
extern const uint8_t lottie_test[];
extern const size_t lottie_test_size;
}

/* Size on screen. The ARGB8888 buffer costs W*H*4 bytes, and ThorVG redraws all of it
 * every frame, so start small (100 to 150) and grow only if FPS allows. */
#define LOTTIE_W        120
#define LOTTIE_H        120

/* The file's own frame rate. lv_lottie assumes 60 fps, so a 30 fps file plays 2x fast
 * unless this is set. lottie_to_c.py prints the value for your file. */
#define LOTTIE_FILE_FPS 60

/* PSRAM is large but slower. If you have spare internal RAM, try MALLOC_CAP_INTERNAL. */
#define LOTTIE_BUF_CAPS (MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT)

lv_obj_t *lottie_demo_create(lv_obj_t *parent)
{
    /* lv_lottie_set_buffer() aligns the pointer itself, so leave room for that */
    const size_t bytes = (size_t)LOTTIE_W * LOTTIE_H * 4 + LV_DRAW_BUF_ALIGN;
    void *buf = heap_caps_malloc(bytes, LOTTIE_BUF_CAPS);
    if (!buf) {
        Serial.printf("lottie: buffer alloc of %u bytes failed (PSRAM free: %u)\n",
                      (unsigned)bytes, (unsigned)ESP.getFreePsram());
        return nullptr;
    }

    lv_obj_t *anim = lv_lottie_create(parent);
    lv_lottie_set_buffer(anim, LOTTIE_W, LOTTIE_H, buf);

    uint32_t t0 = millis();
    lv_lottie_set_src_data(anim, lottie_test, lottie_test_size);   /* parses and renders frame 0 */
    Serial.printf("lottie: loaded in %u ms\n", (unsigned)(millis() - t0));

    /* Play at the file's real speed: duration = frames * 1000 / fps */
    lv_anim_t *a = lv_lottie_get_anim(anim);
    lv_anim_set_duration(a, (uint32_t)a->end_value * 1000 / LOTTIE_FILE_FPS);

    lv_obj_center(anim);
    return anim;
}

void lottie_demo_report(void)
{
    TaskHandle_t t = xTaskGetHandle("lvgl");
    Serial.printf("heap free %u (min %u) | PSRAM free %u | lvgl stack headroom %u bytes\n",
                  (unsigned)ESP.getFreeHeap(), (unsigned)ESP.getMinFreeHeap(),
                  (unsigned)ESP.getFreePsram(),
                  t ? (unsigned)uxTaskGetStackHighWaterMark(t) : 0u);
}
